/// <summary>
/// display the related journal num, only for Allocations
/// </summary>
/// <returns>Ledger Journal Id</returns>
[SysClientCacheDataMethodAttribute(true)]
display LedgerJournalId AVAledgerJournalRelatedToAllocation()
{
    LedgerJournalTable ledgerJournalTable;
    select firstonly JournalNum from  ledgerJournalTable
        where ledgerJournalTable.AVAAllocationRefRecId == this.RecId;
    return ledgerJournalTable.JournalNum;
}
